<?php $title=$wheel_label.' — wheel history'; $pageUrl=static fn(array $changes):string=>'?'.http_build_query(array_merge($query??[],$changes)); ?><?= view('vehicle_wheel_history/_start',get_defined_vars()) ?>
<?= view('vehicle_wheel_history/_strip',['projection'=>$projection]) ?>
<p>Clock positions are referenced with the valve stem at 12 o'clock.</p>
<?php $conflicts=$wheel==='UNKNOWN'?$projection['unknown']['invalid_records']:($projection['wheels'][$wheel]['conflict_records']??[]); if($conflicts!==[]): ?><section aria-label="Conflicting condition records"><h2>Review conflicting records</h2><p>No record has been selected as current truth.</p><ul><?php foreach($conflicts as $conflict): ?><li><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/damage/<?= (int)$conflict['id'] ?>">Review original condition #<?= (int)$conflict['id'] ?></a> · <?= esc($conflict['status_code']) ?></li><?php endforeach; ?></ul><p><?= (int)($wheel==='UNKNOWN'?$projection['unknown']['invalid_count']:$projection['wheels'][$wheel]['conflict_record_count']) ?> records require review.</p><?php if($wheel!=='UNKNOWN'): ?><p><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/damage-ledger?wheel=<?= esc($wheel,'attr') ?>&amp;physical_status=current">View all current wheel conditions</a></p><?php endif; ?></section><?php endif; ?>
<?php if($wheel!=='UNKNOWN'): ?><p><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/wheel-damage/new?wheel_code=<?= esc($wheel,'attr') ?>">Review or record an explicit wheel occurrence</a></p><?php endif; ?>
<section aria-label="Condition episodes"><h2>Condition episodes</h2><p>Each canonical condition is a separate episode. Episode numbers are presentation labels.</p>
<?php if($episodes===[]): ?><p>No episodes recorded.</p><?php endif; ?>
<?php foreach($episodes as $record): ?><article><h3>Episode <?= (int)$record['episode_number'] ?></h3><p><?= esc(\App\Services\Fleet\VehicleDamageService::STATUSES[$record['status_code']]??$record['status_code']) ?> · Discovered <?= esc($record['discovered_at']) ?></p><a href="<?= esc($pageUrl(['episode'=>(int)$record['id'],'timeline_page'=>1,'repair_page'=>1,'after'=>0]),'attr') ?>">Review Episode <?= (int)$record['episode_number'] ?></a></article><?php endforeach; ?>
<nav aria-label="Episode pages"><?php if($episode_page>1): ?><a href="<?= esc($pageUrl(['episode_page'=>$episode_page-1]),'attr') ?>">Previous episodes</a><?php endif; ?><?php if($episode_has_next): ?><a href="<?= esc($pageUrl(['episode_page'=>$episode_page+1]),'attr') ?>">Next episodes</a><?php endif; ?></nav></section>
<?php if($episode!==null): ?><section aria-label="Selected episode"><h2>Selected condition #<?= (int)$episode['id'] ?></h2><p>Physical status: <?= esc(\App\Services\Fleet\VehicleDamageService::STATUSES[$episode['status_code']]) ?> · Severity: <?= esc(\App\Services\Fleet\VehicleDamageService::SEVERITIES[$episode['severity_code']]) ?></p><p><strong>Current condition description</strong><br><?= nl2br(esc($episode['description'])) ?></p><p>Discovered <?= esc($episode['discovered_at']) ?>. Timeline entries retain their recorded descriptions.</p></section>
<section aria-label="Occurrence timeline"><h2>Occurrence timeline</h2><ol><?php foreach($timeline as $row): ?><li><strong><?= esc(\Config\VehicleDamage::EFFECTS[$row['effect']]??ucwords(str_replace('_',' ',$row['effect']))) ?></strong><p>Occurred <?= esc((string)($row['membership_id']!==null?$row['damage_occurred_at']:$row['occurred_at'])) ?: 'time unknown' ?> · Recorded <?= esc((string)$row['recorded_at']) ?></p>
<?php if($row['kind']==='attribution'): ?><?php $before=json_decode($row['before_json']??'{}',true);$after=json_decode($row['after_json']??'{}',true); ?><p>Attribution corrected from <?= esc(\Config\VehicleDamage::ATTRIBUTIONS[$before['attribution_type']??'unknown']??'Not recorded') ?> to <?= esc(\Config\VehicleDamage::ATTRIBUTIONS[$after['attribution_type']??'unknown']??'Not recorded') ?>.</p><?php else: ?><p><?= nl2br(esc((string)($row['note']??$row['new_description']??''))) ?></p><?php endif; ?>
<?php if($row['membership_id']!==null): ?><p>Recorded wheel: <?= esc(\App\Services\Fleet\VehicleWheelIdentity::conditionLabel(['panel_code'=>$row['recorded_panel']])) ?></p><a href="/fleet/vehicles/<?= (int)$vehicle['id'] ?>/wheel-history/<?= (int)$row['original_condition_id'] ?>/occurrences/<?= (int)$row['membership_id'] ?>">Occurrence details, comparison and photos</a><?php endif; ?>
<?php if($row['condition_event_id']===null && $row['kind']==='legacy'): ?><p>Exact condition event not recorded. Comparison basis may be unavailable.</p><?php endif; ?></li><?php endforeach; ?></ol>
<nav aria-label="Timeline pages"><?php if($timeline_page>1): ?><a href="<?= esc($pageUrl(['episode'=>(int)$episode['id'],'timeline_page'=>$timeline_page-1]),'attr') ?>">Previous history</a><?php endif; ?><?php if($timeline_has_next): ?><a href="<?= esc($pageUrl(['episode'=>(int)$episode['id'],'timeline_page'=>$timeline_page+1]),'attr') ?>">Next history</a><?php endif; ?></nav></section>
<section aria-label="Exact episode repair history"><h2>Repair context for this episode</h2><p>Work results belong to this condition only. Job completion does not prove every wheel was repaired.</p><?php if($repairs===[]): ?><p>No repair work membership recorded.</p><?php endif; ?><?php foreach($repairs as $repair): ?><article><p>Repair job #<?= (int)$repair['vehicle_damage_repair_job_id'] ?> · <?= esc($repair['summary']) ?></p><p>This condition’s result: <?= esc(str_replace('_',' ',$repair['result_code'])) ?><?= $repair['withdrawn_at']!==null?' · Withdrawn':'' ?>. Job status: <?= esc(str_replace('_',' ',$repair['job_status'])) ?></p><p><?= esc((string)$repair['note']) ?></p></article><?php endforeach; ?>
<nav aria-label="Repair context pages"><?php if($repair_page>1): ?><a href="<?= esc($pageUrl(['episode'=>(int)$episode['id'],'repair_page'=>$repair_page-1]),'attr') ?>">Previous repair context</a><?php endif; ?><?php if($repair_has_next): ?><a href="<?= esc($pageUrl(['episode'=>(int)$episode['id'],'repair_page'=>$repair_page+1]),'attr') ?>">Next repair context</a><?php endif; ?></nav></section>
<?= view('vehicle_wheel_history/_gallery',['heading'=>'Episode evidence — occurrence unknown','gallery'=>$episode_evidence,'pageUrl'=>$pageUrl,'cursorKey'=>'after','occurrenceRecordedAt'=>null]) ?>
